"""Generates `Proof/Wg0/Gen/NumLo.lean`: the score words of the low half (registers 2886-2917)
at the stages of the peer packs hold the words of the load. Run from the repository root."""

from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
OUT = ROOT / "Kernels/FlashMlaSparseDecodeH64/Proof/Wg0/Gen/NumLo.lean"

HEAD = """-- SPDX-License-Identifier: Apache-2.0
-- Generated by Kernels/FlashMlaSparseDecodeH64/Gen/w0cond_lo_gen.py; do not edit.
-- domain: consistent
module

public import Kernels.FlashMlaSparseDecodeH64.Proof.Wg0.Data.NumFrame

@[expose] public section

/-! # The low half's words along the peer packs

The peer pack `k` reads the registers `2886 + 4 k` to `2889 + 4 k`, which hold the words of the
low half's load (`lo`). Between two stages of the pack chain a register of a later pack is live and
no key of the run's facts, so it keeps its value. -/

namespace PTX.Kernels.FlashMlaSparseDecodeH64.Proof.Wg0.Data
open PTX PTX.Flow PTX.Proof PTX.Kernels.FlashMlaSparseDecodeH64.Proof.Wg0.Gen

noncomputable section

variable {x : BitVec 64} {m l mx sk : Value} {lo hi : List Value} {mw : Value}

/-- The register of column `c` of the low half holds the load's word. -/
theorem w0c_vm_lo (hlen : lo.length = 32) (c : Nat) (hc : c < 32) :
    lookupD (s_vm x m l mx sk lo hi mw) (2886 + c) = lo.getD c (.pred false) := by
  have hr : 2886 + c ∈ loRegs := by
    simp only [loRegs, List.mem_range'_1]; omega
  unfold s_vm f_sldw
  rw [lk_snoc (by
    simp only [List.zip_cons_cons, List.zip_nil_left, List.map_cons, List.map_nil, List.mem_cons,
      List.not_mem_nil, or_false]
    omega)]
  rw [lk_head_mem (by
    simpa only [factsFrom, List.map_map, Function.comp_def, List.map_id'] using hr)]
  have hrr : loRegs = List.range' 2886 lo.length := by simp [loRegs, hlen]
  have hz : (loRegs.zip lo).lookup (2886 + c) = some (lo[c]'(by omega)) := by
    rw [hrr]; exact lookup_range_zip 2886 lo c (by omega)
  unfold lookupD
  rw [lookup_factsFrom_mem hr]
  simp only [hz, Option.getD_some]
  simp [List.getD_eq_getElem?_getD, List.getElem?_eq_getElem (show c < lo.length by omega)]

/-- The registers of the low half's words, kept by the masks. -/
theorem w0c_lo_mvm : ∀ r ∈ loRegs,
    lookupD (m_vm x m l mx sk lo hi mw) r = lookupD (s_vm x m l mx sk lo hi mw) r := by
  intro r hr
  unfold m_vm
  exact lk_frame (K := loRegs) (by decide)
    (by simp only [mask_facts4, List.map_cons, List.map_nil]; decide) hr

"""
out = [HEAD]
prev = "m_vm"
for j in range(7):
    lo = 2890 + 4 * j
    out.append(f"""/-- The words of the low half from `{lo}` on, kept by the peer pack `{j}`. -/
def w0KeepLo{j} : List Nat := List.range' {lo} {2918 - lo}

theorem w0c_lo_pst{j} : ∀ r ∈ w0KeepLo{j},
    lookupD (f_pst{j} x m l mx sk lo hi mw) r = lookupD ({prev} x m l mx sk lo hi mw) r := by
  intro r hr
  unfold f_pst{j}
  exact lk_frame (K := w0KeepLo{j}) (by decide)
    (by simp only [pk{394 + 10 * j}_facts1, List.map_cons, List.map_nil]; decide) hr

""")
    prev = f"f_pst{j}"

# the value of register 2886 + c at the stage of the pack k
for k in range(8):
    stage = "m_vm" if k == 0 else f"f_pst{k - 1}"
    c0 = 4 * k
    steps = [
        f"w0c_lo_pst{j} _ (by simp only [w0KeepLo{j}, List.mem_range'_1]; omega)"
        for j in range(k - 1, -1, -1)
    ]
    steps.append("w0c_lo_mvm _ (by simp only [loRegs, List.mem_range'_1]; omega)")
    chain = ",\n    ".join(steps)
    out.append(f"""/-- The register of column `c` (from `{c0}`) at the stage of the peer pack `{k}`. -/
theorem w0c_lo_at{k} (hlen : lo.length = 32) (c : Nat) (hc : {c0} ≤ c) (hc2 : c < 32) :
    lookupD ({stage} x m l mx sk lo hi mw) (2886 + c) = lo.getD c (.pred false) := by
  rw [{chain}]
  exact w0c_vm_lo hlen c hc2

""")
out.append("end\nend PTX.Kernels.FlashMlaSparseDecodeH64.Proof.Wg0.Data\n")
OUT.write_text("".join(out))
